CREATE TABLE "Project" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "DesignDraft" ("id" TEXT PRIMARY KEY, "projectId" TEXT NOT NULL UNIQUE, "schemaVersion" INTEGER NOT NULL, "revision" INTEGER NOT NULL DEFAULT 0, "designJson" JSONB NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "DesignDraft_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE);
CREATE TABLE "DesignVersion" ("id" TEXT PRIMARY KEY, "projectId" TEXT NOT NULL, "schemaVersion" INTEGER NOT NULL, "designJson" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "DesignVersion_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE);
CREATE TABLE "ModuleCatalogEntry" ("id" TEXT PRIMARY KEY, "definitionId" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "definitionJson" JSONB NOT NULL, "versionJson" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "DesignVersion_projectId_idx" ON "DesignVersion"("projectId");
